INSERT INTO raw_material_properties (raw_material_id, property_key, value_num, value_text, unit, source_version)
SELECT t.id, p.property_key, CAST(p.value_num AS NUMERIC), CAST(p.value_text AS TEXT), CAST(p.unit AS TEXT), '2026-StretchForm'
FROM props p
JOIN src s ON s.material = p.source_name
JOIN LATERAL (
  SELECT rm.id FROM raw_materials rm
  WHERE rm.material = s.material_name
  ORDER BY (rm.material_group = 'Sheet Metal Stretch Forming') DESC
  LIMIT 1
) t ON true
ON CONFLICT (raw_material_id, property_key) DO NOTHING;

-- ── Sheet Metal Transfer Die: core columns (102 materials, policy suffix)
WITH src AS (
  SELECT v.*,
    CASE WHEN EXISTS (SELECT 1 FROM raw_materials rm WHERE rm.material = v.material AND rm.material_group IS DISTINCT FROM 'Sheet Metal Transfer Die')
         THEN v.material || ' (Sheet Metal Transfer Die)' ELSE v.material END AS material_name
  FROM (VALUES
  ($str$Generic Aluminum, AA 1100$str$, $str$Aluminum, AA 1100$str$, $str$Aluminum$str$, $str$Sheet Metal Transfer Die$str$, 30.11, 6.751, 6.751, $str$Cost per KG$str$, 6.751, $str$USD$str$, 2700, 2.7, 60, $str$Brinell$str$, $str$Grade 1100$str$, NULL, $str$Aluminum, AA 1100$str$),
  ($str$Generic Aluminum, AA 2219$str$, $str$Aluminum, AA 2219$str$, $str$Aluminum$str$, $str$Sheet Metal Transfer Die$str$, 30.11, 7.194, 7.194, $str$Cost per KG$str$, 7.194, $str$USD$str$, 3100, 3.1, 60, $str$Brinell$str$, $str$Grade 2219$str$, NULL, $str$Aluminum, AA 2219$str$),
  ($str$Generic Aluminum, AA 3105$str$, $str$Aluminum, AA 3105$str$, $str$Aluminum$str$, $str$Sheet Metal Transfer Die$str$, 30.11, 6.607, 6.607, $str$Cost per KG$str$, 6.607, $str$USD$str$, 2800, 2.8, 60, $str$Brinell$str$, $str$Grade 3105$str$, NULL, $str$Aluminum, AA 3105$str$),
